#!/bin/sh
# 202 — COMFORT (for the G.723.1 comfort-noise generator)
#
# When nobody on a phone call is speaking, the line goes quiet and the receiving
# codec invents "comfort noise" so you know you are still connected. G.723.1 does
# this from a 4-byte SID frame (a spectral envelope and a gain) and keeps doing it,
# smoothly, through every "untransmitted" 1-byte frame that follows.
#
# In this decoder's grammar the first byte of each frame says what kind it is, by its
# two low bits. Letters b f j n r v z begin a 4-byte SID frame; letters c g k o s w
# are one-byte "nothing was sent" frames, 30 ms each. So a word like "bool" is a
# colour of noise and every "o" after it holds that colour for one more frame;
# "o"s before the first word are silence. The score below is literally that: eight
# voices, each a word and a long breath of o's. The texts are the whole piece.
#
# Many 4-letter SID words decode to a noise so resonant it is a whistle (the LSP
# codebook places a pole almost on the unit circle). "bool" whistles at 2235.2 Hz.
# Slowed with asetrate, the whistle becomes a breathing sine (bandwidth ~0.3 Hz)
# and each o becomes ~0.3..0.9 s. The voices run at asetrate 262*k/2 (k = 2,3,4,5,6,7,9,12):
# the overtone series of D (73.2 Hz) — D2 A2 D3 F#3 A3 C4(7th) E4 A4.
# G.723.1 predicts each SID's spectrum from the previous one, so a word's pitch
# depends on the word said before it (I measured every 4-letter SID word in the
# dictionary after each context: tools/sidmap.py). Two sentences result:
#    bool . zeus . rapt           1 -> 3/5 (-2c) -> 1 (+8c)
#    bool . vert . brin . root    1 -> 3/4 (-12c) -> 3/5 (+2c) -> 1 (-17c)
# At 1:36 the even voices say "vert" and fall a fourth (an open sus chord; A4 and E4
# meet 12 cents apart and beat). At 3:12 every voice says "zeus" or "brin" and the
# whole overtone chord drops a just major sixth, D to F (sub at 44 Hz). At 4:48
# "rapt"/"root": home, but not exactly - the two sentences come back 25 cents apart. The comfort-noise gain smoother swells each new word in by
# itself. Right channel = left shifted +0.28 Hz (afreqshift): every voice beats
# between the ears at the same 0.28 Hz, so the chord breathes as one body (Radigue).
# Above it all, "razz" sped up to 13.4 kHz: a faint high breath, looped every 6 s.
# (o-runs were counted with tools/comfort.py; what is here is literal.)
ffmpeg -hide_banner -y \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -f g723_1 -i "data:," \
 -filter_complex "
 [0]asetrate=262,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=60/8,afade=t=out:st=376:d=14,asplit[l0][r0];
 [1]asetrate=393,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=48/8,afade=t=out:st=370:d=14,asplit[l1][r1];
 [2]asetrate=524,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=45/8,afade=t=out:st=376:d=14,asplit[l2][r20];[r20]afreqshift=shift=0.28[r2];
 [3]asetrate=655,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=36/8,afade=t=out:st=358:d=14,asplit[l3][r30];[r30]afreqshift=shift=0.28[r3];
 [4]asetrate=786,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=33/8,afade=t=out:st=352:d=14,asplit[l4][r40];[r40]afreqshift=shift=0.28[r4];
 [5]asetrate=917,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=24/8,afade=t=out:st=342:d=14,asplit[l5][r50];[r50]afreqshift=shift=0.28[r5];
 [6]asetrate=1179,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=21/8,afade=t=out:st=330:d=14,asplit[l6][r60];[r60]afreqshift=shift=0.28[r6];
 [7]asetrate=1572,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,highpass=f=30,volume=18/8,afade=t=out:st=322:d=14,asplit[l7][r70];[r70]afreqshift=shift=0.28[r7];
 [8]asetrate=47800,aresample=48000,aformat=channel_layouts=mono,asetpts=N/SR/TB,atrim=start=1,asetpts=N/SR/TB,aloop=loop=-1:size=240000,highpass=f=6000,volume=0.9,aeval='val(0)*clip((t-96)/40,0,1)*clip((300-t)/40,0,1)',asplit[lh][rh0];[rh0]adelay=1500[rh];
 [l0][l1][l2][l3][l4][l5][l6][l7][lh]amix=inputs=9:normalize=0[L];
 [r0][r1][r2][r3][r4][r5][r6][r7][rh]amix=inputs=9:normalize=0[R];
 [L][R]amerge=inputs=2,volume=1.5,alimiter=level=0:limit=0.8:attack=20:release=200
 " -t 390 "$@"
